const LG=(id,a,b,x2,y2)=>`<linearGradient id="${id}" x1="0" y1="0" x2="${x2??0}" y2="${y2??1}"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient>`;
const RG=(id,a,b,cx,cy,r)=>`<radialGradient id="${id}" cx="${cx??.38}" cy="${cy??.32}" r="${r??.75}"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></radialGradient>`;
const HL=(id)=>`<radialGradient id="${id}"><stop offset="0" stop-color="#fff" stop-opacity=".75"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient>`;
const tube=(x1,y1,x2,y2,w,fill,st)=>{const dx=x2-x1,dy=y2-y1,l=Math.hypot(dx,dy),nx=-dy/l*w/2,ny=dx/l*w/2;
  return `<path d="M${x1+nx} ${y1+ny} L${x2+nx} ${y2+ny} L${x2-nx} ${y2-ny} L${x1-nx} ${y1-ny} Z" fill="${fill}" stroke="${st}" stroke-width="1.3" stroke-linejoin="round"/>`;};
